import{_ as a,c as r,o as t,ag as o}from"./chunks/framework.CQuhCYrb.js";const f=JSON.parse('{"title":"RF/SDR/Communications","description":"","frontmatter":{"title":"RF/SDR/Communications"},"headers":[],"relativePath":"radio/index.md","filePath":"radio/index.md","lastUpdated":null}'),i={name:"radio/index.md"};function n(l,e,s,d,h,c){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="rf-sdr-communications" tabindex="-1">RF/SDR/Communications <a class="header-anchor" href="#rf-sdr-communications" aria-label="Permalink to &quot;RF/SDR/Communications&quot;">​</a></h1><p>Software defined radio, DragonOS, Flipper Zero, HAM radio licensing, and RF communications resources.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Resource</th><th>Description</th></tr></thead><tbody><tr><td><a href="/radio/software-defined-radios-sdrs.html">Software Defined Radios (SDRs)</a></td><td>Introduction to SDR concepts and hardware</td></tr><tr><td><a href="/radio/dragonos.html">DragonOS</a></td><td>Pre-configured Linux for SDR operations</td></tr><tr><td><a href="/radio/ham-radio.html">HAM Radio</a></td><td>Amateur radio licensing and resources</td></tr></tbody></table><h2 id="software-defined-radio-sdr" tabindex="-1">Software Defined Radio (SDR) <a class="header-anchor" href="#software-defined-radio-sdr" aria-label="Permalink to &quot;Software Defined Radio (SDR)&quot;">​</a></h2><h3 id="what-is-sdr" tabindex="-1">What is SDR? <a class="header-anchor" href="#what-is-sdr" aria-label="Permalink to &quot;What is SDR?&quot;">​</a></h3><p>Software-defined radio (SDR) is a radio communication system where components traditionally implemented in analog hardware (mixers, filters, amplifiers, modulators/demodulators) are instead implemented using software on a computer or embedded system.</p><h3 id="sdr-hardware" tabindex="-1">SDR Hardware <a class="header-anchor" href="#sdr-hardware" aria-label="Permalink to &quot;SDR Hardware&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Device</th><th>Use Case</th><th>Notes</th></tr></thead><tbody><tr><td><strong>RTL-SDR</strong></td><td>Entry-level</td><td>Receive only, inexpensive</td></tr><tr><td><strong>HackRF One</strong></td><td>General purpose</td><td>Transmit and receive, wide frequency range</td></tr><tr><td><strong>PlutoSDR</strong></td><td>Learning/Teaching</td><td>Great with PySDR, networkable, FPGA capable</td></tr><tr><td><strong>LimeSDR</strong></td><td>Advanced</td><td>Full duplex, high bandwidth</td></tr><tr><td><strong>BladeRF</strong></td><td>Professional</td><td>High performance</td></tr></tbody></table><h3 id="getting-started-with-sdr" tabindex="-1">Getting Started with SDR <a class="header-anchor" href="#getting-started-with-sdr" aria-label="Permalink to &quot;Getting Started with SDR&quot;">​</a></h3><p><strong>Recommended for Learning</strong>: PlutoSDR + PySDR</p><ul><li>Can be networked for remote learning</li><li>Supports Maia firmware for 50MHz+ spectrum via FPGA</li><li>Can be hacked for LTE support</li><li>Available at Mouser Electronics</li></ul><h3 id="sdr-software-platforms" tabindex="-1">SDR Software &amp; Platforms <a class="header-anchor" href="#sdr-software-platforms" aria-label="Permalink to &quot;SDR Software &amp; Platforms&quot;">​</a></h3><ul><li><a href="/radio/dragonos.html">DragonOS</a> - Pre-configured Linux with SDR software suite</li><li><a href="https://www.gnuradio.org/" target="_blank" rel="noreferrer">GNU Radio</a> - Open-source signal processing toolkit</li><li><a href="https://www.sdrpp.org/" target="_blank" rel="noreferrer">SDR++</a> - Cross-platform SDR software</li><li><a href="https://gqrx.dk/" target="_blank" rel="noreferrer">GQRX</a> - Open source SDR receiver</li></ul><h2 id="dragonos" tabindex="-1">DragonOS <a class="header-anchor" href="#dragonos" aria-label="Permalink to &quot;DragonOS&quot;">​</a></h2><p><a href="/radio/dragonos.html">DragonOS</a> leverages Lubuntu Linux as a delivery package for pre-installed open-source SDR software.</p><h3 id="supported-platforms" tabindex="-1">Supported Platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported Platforms&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Platform</th><th>Notes</th></tr></thead><tbody><tr><td>VirtualBox</td><td>Virtualized</td></tr><tr><td>VMware</td><td>Virtualized</td></tr><tr><td>Raspberry Pi 3/4</td><td>Native ARM</td></tr><tr><td>Intel</td><td>Native x86</td></tr></tbody></table><h3 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h3><ol><li><a href="https://sourceforge.net/projects/dragonos-focal/files/latest/download" target="_blank" rel="noreferrer">Download from SourceForge</a></li><li>Prepare USB with <a href="https://www.ventoy.net/en/download.html" target="_blank" rel="noreferrer">Ventoy</a> or <a href="https://www.balena.io/etcher/" target="_blank" rel="noreferrer">Etcher</a></li><li>Boot from live image or install dual-boot</li></ol><h3 id="dragonos-resources" tabindex="-1">DragonOS Resources <a class="header-anchor" href="#dragonos-resources" aria-label="Permalink to &quot;DragonOS Resources&quot;">​</a></h3><ul><li><a href="/radio/dragonos.html">DragonOS Guide</a> - Full installation and usage guide</li><li><a href="https://www.youtube.com/channel/UC9U2kaqhE716J2WNSTcOghg" target="_blank" rel="noreferrer">YouTube Channel</a> - Video tutorials</li><li><a href="https://discord.gg/9uSC2un" target="_blank" rel="noreferrer">Discord Community</a></li><li><a href="https://matrix.to/#/#dragon-os:matrix.org" target="_blank" rel="noreferrer">Matrix Channels</a></li></ul><h3 id="pre-configured-products" tabindex="-1">Pre-configured Products <a class="header-anchor" href="#pre-configured-products" aria-label="Permalink to &quot;Pre-configured Products&quot;">​</a></h3><ul><li><a href="https://cemaxecuter.com/?post_type=product" target="_blank" rel="noreferrer">WarDragon Kit+</a> - Ready-to-use SDR kit</li></ul><h2 id="ham-radio" tabindex="-1">HAM Radio <a class="header-anchor" href="#ham-radio" aria-label="Permalink to &quot;HAM Radio&quot;">​</a></h2><h3 id="license-classes-us" tabindex="-1">License Classes (US) <a class="header-anchor" href="#license-classes-us" aria-label="Permalink to &quot;License Classes (US)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>License</th><th>Privileges</th><th>Exam</th></tr></thead><tbody><tr><td><strong>Technician</strong></td><td>VHF/UHF, local/regional comms</td><td>35 questions</td></tr><tr><td><strong>General</strong></td><td>HF privileges, worldwide comms</td><td>35 questions</td></tr><tr><td><strong>Amateur Extra</strong></td><td>All privileges, all bands</td><td>50 questions</td></tr></tbody></table><p>Licenses valid for 10 years. See <a href="https://www.arrl.org/getting-licensed" target="_blank" rel="noreferrer">ARRL Getting Licensed</a>.</p><h3 id="study-resources" tabindex="-1">Study Resources <a class="header-anchor" href="#study-resources" aria-label="Permalink to &quot;Study Resources&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Resource</th><th>Link</th></tr></thead><tbody><tr><td>Ham Cram</td><td><a href="http://ham-cram.com/member-lounge/technician-study.php" target="_blank" rel="noreferrer">ham-cram.com</a></td></tr><tr><td>ARRL Exam Practice</td><td><a href="https://www.arrl.org/exam-practice" target="_blank" rel="noreferrer">arrl.org/exam-practice</a></td></tr><tr><td>Technician Anki Deck</td><td><a href="https://ankiweb.net/shared/info/1989339803" target="_blank" rel="noreferrer">Anki Flashcards</a></td></tr><tr><td>Extra Class Anki Deck</td><td><a href="https://ankiweb.net/shared/info/817192394" target="_blank" rel="noreferrer">Anki Flashcards</a></td></tr></tbody></table><h3 id="find-exam-sessions" tabindex="-1">Find Exam Sessions <a class="header-anchor" href="#find-exam-sessions" aria-label="Permalink to &quot;Find Exam Sessions&quot;">​</a></h3><p><a href="https://www.arrl.org/find-an-amateur-radio-license-exam-session" target="_blank" rel="noreferrer">ARRL Exam Session Finder</a> - In-person and online testing</p><p>See: <a href="/radio/ham-radio.html">HAM Radio Guide</a></p><h2 id="flipper-zero" tabindex="-1">Flipper Zero <a class="header-anchor" href="#flipper-zero" aria-label="Permalink to &quot;Flipper Zero&quot;">​</a></h2><p><a href="/radio/flipper-zero.html">Flipper Zero</a> - Multi-tool device for pentesters and RF enthusiasts.</p><h3 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h3><ul><li><a href="https://flipc.org/" target="_blank" rel="noreferrer">Flipc.org</a> - Collection of Flipper Zero applications</li><li><a href="https://github.com/playmean/fap-list" target="_blank" rel="noreferrer">GitHub: fap-list</a> - .fap files built automatically</li></ul><h2 id="radio-operations" tabindex="-1">Radio Operations <a class="header-anchor" href="#radio-operations" aria-label="Permalink to &quot;Radio Operations&quot;">​</a></h2><ul><li><a href="/radio/radio-checks.html">Radio Checks</a> - Proper radio check procedures</li></ul><h2 id="related-topics" tabindex="-1">Related Topics <a class="header-anchor" href="#related-topics" aria-label="Permalink to &quot;Related Topics&quot;">​</a></h2><h3 id="electronic-warfare" tabindex="-1">Electronic Warfare <a class="header-anchor" href="#electronic-warfare" aria-label="Permalink to &quot;Electronic Warfare&quot;">​</a></h3><p>SDR knowledge applies to understanding EW concepts:</p><ul><li>Signal analysis and identification</li><li>Spectrum monitoring</li><li>Communications security</li></ul><h3 id="unmanned-systems" tabindex="-1">Unmanned Systems <a class="header-anchor" href="#unmanned-systems" aria-label="Permalink to &quot;Unmanned Systems&quot;">​</a></h3><p>RF knowledge is critical for:</p><ul><li>Command and control links (ELRS, Crossfire)</li><li>Video transmission (5.8GHz FPV)</li><li>GPS/GNSS systems</li><li>Counter-UAS jamming</li></ul><p>See: <a href="/general/unmanned-systems.html">Unmanned Systems</a></p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><h3 id="books" tabindex="-1">Books <a class="header-anchor" href="#books" aria-label="Permalink to &quot;Books&quot;">​</a></h3><ul><li>Dillinger, Markus et al. (2003). <em>Software Defined Radio: Architectures, Systems, and Functions</em>. Wiley &amp; Sons.</li><li>Amaral, Cristiano (2021). <em>Guia Moderno do Radioescuta</em>. Brazil: Amazon.</li></ul><h3 id="external-resources" tabindex="-1">External Resources <a class="header-anchor" href="#external-resources" aria-label="Permalink to &quot;External Resources&quot;">​</a></h3><ul><li><a href="https://en.wikipedia.org/wiki/Software-defined_radio" target="_blank" rel="noreferrer">Wikipedia: Software-defined radio</a></li><li><a href="https://sourceforge.net/p/dragonos-focal/wiki/Home/" target="_blank" rel="noreferrer">DragonOS SourceForge Wiki</a></li><li><a href="https://www.wirelessinnovation.org/" target="_blank" rel="noreferrer">Wireless Innovation Forum</a></li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="/general/unmanned-systems.html">Unmanned Systems</a> - RF links for drones</li><li><a href="/general/counter-uxs.html">Counter-UxS</a> - Electronic warfare concepts</li><li><a href="/general/certifications.html">Certifications</a> - RF/EW certifications</li></ul>',54)])])}const m=a(i,[["render",n]]);export{f as __pageData,m as default};
